function auditCodeSnippet(code){const lines=code.split("\n");const findings=[];lines.forEach((line,idx)=>{AST_RULES_V300.forEach(rule=>{if(rule.regex.test(line)){findings.push({line:idx+1,rule:rule.name,severity:rule.severity,message:rule.msg,snippet:line.trim()});}});});return findings;}
