function initWaveform(){const cv=document.getElementById("waveCanvas");if(!cv)return;const ctx=cv.getContext("2d");let dpr=window.devicePixelRatio||1;let rect=cv.getBoundingClientRect();cv.width=rect.width*dpr;cv.height=rect.height*dpr;ctx.scale(dpr,dpr);let width=rect.width;let height=rect.height;let history=new Array(72).fill(height/2);let tick=0;function loop(){tick+=0.06;let base=height/2;let osc=Math.sin(tick*1.5)*12+Math.cos(tick*3.0)*6;let burst=Math.sin(tick*0.4)>0.85?Math.sin(tick*6)*14:0;let val=Math.max(8,Math.min(height-8,base+osc+burst));history.shift();history.push(val);ctx.clearRect(0,0,width,height);ctx.fillStyle="#07080b";ctx.fillRect(0,0,width,height);ctx.strokeStyle="#1e222b";ctx.lineWidth=1;for(let y=18;y<height;y+=22){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(width,y);ctx.stroke();}ctx.strokeStyle="#f1f5f9";ctx.lineWidth=1.8;ctx.beginPath();const step=width/(history.length-1);for(let i=0;i<history.length;i++){let x=i*step;let y=history[i];if(i===0){ctx.moveTo(x,y);}else{let prevX=(i-1)*step;let prevY=history[i-1];let midX=(prevX+x)/2;ctx.quadraticCurveTo(prevX,prevY,midX,(prevY+y)/2);}}ctx.lineTo(width,history[history.length-1]);ctx.stroke();requestAnimationFrame(loop);}requestAnimationFrame(loop);window.addEventListener("resize",()=>{rect=cv.getBoundingClientRect();cv.width=rect.width*dpr;cv.height=rect.height*dpr;ctx.scale(dpr,dpr);width=rect.width;height=rect.height;});}
