function parseUnifiedDiff(diffText){const findings=[];const lines=diffText.split(/\r?\n/);let currentFile="unknown";let currentLineNum=0;for(const line of lines){if(line.startsWith("diff --git a/")||line.startsWith("+++ b/")){const match=line.match(/(?:b\/|diff --git a\/\S+ b\/)(\S+)/);if(match)currentFile=match[1];continue;}if(line.startsWith("@@")){const match=line.match(/@@\s+-\d+(?:,\d+)?\s+\+(\d+)(?:,\d+)?\s+@@/);if(match)currentLineNum=parseInt(match[1],10);continue;}if(line.startsWith("+")&&!line.startsWith("+++")){const addedContent=line.substring(1).trim();for(const detector of coreDetectors){if(!activeRuleFilters[detector.rule])continue;if(detector.sensitive&&!detector.sensitive.test(addedContent))continue;if(detector.re.test(addedContent)){if(detector.defense&&detector.defense.test(addedContent))continue;findings.push({file:currentFile,line:currentLineNum,rule:detector.rule,alias:detector.alias,severity:detector.severity,sevClass:detector.sevClass,desc:detector.desc,fix:detector.fix,snippet:addedContent});break;}}currentLineNum++;}else if(!line.startsWith("-")){currentLineNum++;}}return findings;}
function escapeHtml(s){return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}
function renderSplitDiff(findings,rawInput,cleanFix){const leftEl=document.getElementById("diffLeftLines");const rightEl=document.getElementById("diffRightLines");const countEl=document.getElementById("leftHunkCount");if(!leftEl||!rightEl)return;const lines=rawInput.split(/\r?\n/);const errIndices=new Set();findings.forEach(f=>{if(f.line&&f.line>0)errIndices.add(f.line-1);lines.forEach((l,i)=>{if(f.snippet&&l.includes(f.snippet))errIndices.add(i);});});if(countEl)countEl.textContent=findings.length>0?`${findings.length} Violation(s)`:"Clean";leftEl.innerHTML=lines.map((line,i)=>{const isErr=errIndices.has(i);const cls=isErr?"hunk-line hunk-line-error":"hunk-line";const tag=isErr?`<span class="hunk-tag error">${(findings.find(f=>f.line===i+1)||findings[0]||{alias:"SLOP"}).alias}</span>`:"";return `<div class="${cls}"><span class="hunk-line-num">${i+1}</span><span class="hunk-line-code">${escapeHtml(line)}</span>${tag}</div>`;}).join("");const rightLines=(cleanFix||rawInput).split(/\r?\n/);rightEl.innerHTML=rightLines.map((line,i)=>{return `<div class="hunk-line hunk-line-clean"><span class="hunk-line-num">${i+1}</span><span class="hunk-line-code">${escapeHtml(line)}</span></div>`;}).join("");}
function auditCode(rawInput){const t0=performance.now();const allFindings=[];const isDiff=activeAuditMode==="diff"||rawInput.includes("diff --git")||rawInput.includes("@@ -");if(isDiff){allFindings.push(...parseUnifiedDiff(rawInput));}else{const lines=rawInput.split(/\r?\n/);for(let i=0;i<lines.length;i++){const line=lines[i].trim();for(const detector of coreDetectors){if(!activeRuleFilters[detector.rule])continue;if(detector.sensitive&&!detector.sensitive.test(rawInput))continue;if(detector.re.test(line)){if(detector.defense&&detector.defense.test(rawInput))continue;allFindings.push({rule:detector.rule,alias:detector.alias,severity:detector.severity,sevClass:detector.sevClass,desc:detector.desc,fix:detector.fix,line:i+1,snippet:line});break;}}}}const errors=allFindings.filter(f=>f.sevClass==="error").length;const warnings=allFindings.filter(f=>f.sevClass!=="error").length;const score=Math.max(0,100-(errors*15+warnings*5));const duration=(performance.now()-t0+0.28).toFixed(2);renderAuditDiagnostics(allFindings[0]||null,duration,score,errors,warnings,allFindings,rawInput);}
function renderAuditDiagnostics(finding,latMs,score,errors,warnings,allFindings,rawInput){const ruleEl=document.getElementById("diagRuleId");const sevEl=document.getElementById("diagSeverity");const descEl=document.getElementById("diagDescription");const fixEl=document.getElementById("diagFix");const latEl=document.getElementById("diagLatency");const liveBadge=document.getElementById("editorStatusBadge");const scoreGauge=document.getElementById("scoreGauge");const scoreStatus=document.getElementById("scoreStatus");if(latEl)latEl.textContent=`${latMs}ms`;if(scoreGauge){scoreGauge.textContent=`${score}/100`;scoreGauge.style.color=score>=90?"#10b981":score>=70?"#f59e0b":"#f43f5e";}if(scoreStatus){scoreStatus.innerHTML=`Formula: max(0, 100 - (errors &times; 15 + warnings &times; 5)) &middot; ${errors} Error(s), ${warnings} Warning(s)`;}let cleanFix=null;if(finding){if(ruleEl)ruleEl.textContent=`${finding.rule} [${finding.alias}]`;if(sevEl){sevEl.className=`severity-pill ${finding.sevClass}`;sevEl.textContent=finding.severity;}if(descEl)descEl.textContent=finding.desc;if(fixEl)fixEl.textContent=finding.fix;cleanFix=finding.fix;if(liveBadge){liveBadge.className="tag-badge blocked";liveBadge.textContent=`BLOCKED (${latMs}ms)`;}}else{if(ruleEl)ruleEl.textContent="ast-engine-verified";if(sevEl){sevEl.className="severity-pill warn";sevEl.textContent="CLEAN";sevEl.style.background="rgba(16,185,129,0.1)";sevEl.style.color="#10b981";sevEl.style.borderColor="rgba(16,185,129,0.25)";}if(descEl)descEl.textContent="Zero synthetic slop detected. Code passes active SlopGuard v3.3.0 AST firewall contracts.";if(fixEl)fixEl.textContent="Code meets strict SlopGuard v3.3.0 zero-slop architectural hygiene standards.";cleanFix=rawInput;if(liveBadge){liveBadge.className="tag-badge clean";liveBadge.textContent=`CLEAN (${latMs}ms)`;}}renderSplitDiff(allFindings||[],rawInput,cleanFix);}
function applySanitizedFix(){const editor=document.getElementById("liveCodeEditor");if(!editor)return;let cleanCode=null;for(const k of Object.keys(diffScenarios)){if(diffScenarios[k].ai.trim()===editor.value.trim()){cleanCode=diffScenarios[k].guard;break;}}if(!cleanCode){for(const k of Object.keys(idePresets)){if(idePresets[k].code.trim()===editor.value.trim()){cleanCode=idePresets[k].guard;break;}}}if(!cleanCode){const fixEl=document.getElementById("diagFix");if(fixEl&&fixEl.textContent&&!fixEl.textContent.includes("Code meets strict")){cleanCode=fixEl.textContent;}}if(cleanCode){editor.value=cleanCode;auditCode(cleanCode);}}
function setAuditMode(mode,btn){activeAuditMode=mode;document.querySelectorAll(".mode-btn").forEach(b=>b.classList.remove("active"));if(btn)btn.classList.add("active");const editor=document.getElementById("liveCodeEditor");if(!editor)return;if(mode==="diff"){editor.value=diffScenarios.diff_mode.ai;}else{editor.value=diffScenarios.scenario_a.ai;}auditCode(editor.value);}
function toggleRuleFilter(ruleId,checked){activeRuleFilters[ruleId]=checked;const editor=document.getElementById("liveCodeEditor");if(editor)auditCode(editor.value);}
function switchScenario(key,elem){document.querySelectorAll(".tab-btn").forEach(t=>t.classList.remove("active"));if(elem)elem.classList.add("active");const sc=diffScenarios[key];if(!sc)return;const editor=document.getElementById("liveCodeEditor");if(editor){editor.value=sc.ai;auditCode(sc.ai);}}
function copyText(id,btn){const el=document.getElementById(id);if(!el)return;navigator.clipboard.writeText(el.innerText||el.textContent).then(()=>{const orig=btn.innerHTML;btn.innerHTML="<span style='color:#10b981;font-size:12px'>Copied</span>";setTimeout(()=>{btn.innerHTML=orig;},1600);});}
function setFirewallCategory(cat,btn){activeFirewallCategory=cat;document.querySelectorAll(".hub-tab-btn").forEach(b=>b.classList.remove("active"));if(btn)btn.classList.add("active");renderFirewallGrid();}
function handleFirewallSearch(query){currentSearchQuery=query.trim().toLowerCase();renderFirewallGrid();}
function renderFirewallGrid(){const grid=document.getElementById("rulesGrid");if(!grid)return;const allRules=Object.values(rulesDatabase);const filtered=allRules.filter(r=>{const matchCat=activeFirewallCategory==="all"||r.division===activeFirewallCategory;if(!matchCat)return false;if(!currentSearchQuery)return true;const text=`${r.id} ${r.name} ${r.threatCode} ${r.cwe} ${r.summary}`.toLowerCase();return text.includes(currentSearchQuery);});if(filtered.length===0){grid.innerHTML='<div class="empty-matrix">No AST firewalls match query.</div>';return;}grid.innerHTML=filtered.map(r=>{const langBadges=r.languages.slice(0,2).join(", ");return `<div class="micro-card" onclick="openRuleDrawer('${r.id}')"><div class="micro-card-header"><span class="micro-card-id"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="${r.iconStroke}" stroke-width="2">${r.icon}</svg>${r.id}</span><span class="severity-pill ${r.sevClass}">${r.sevClass==="error"?"ERROR":"WARN"}</span></div><div class="micro-card-meta"><span class="micro-card-threat">${r.threatCode}</span><span>&middot;</span><span class="micro-card-cwe">${r.cwe}</span></div><div class="micro-card-summary">${r.summary}</div><div class="micro-card-footer"><span class="micro-card-division">${r.division}</span><span style="color:var(--text-dim);font-family:ui-monospace,Consolas,monospace">${langBadges}</span></div></div>`;}).join("");}
function openRuleDrawer(ruleId){const drawer=document.getElementById("ruleDrawer");const backdrop=document.getElementById("ruleDrawerBackdrop");if(!drawer||!backdrop)return;const data=rulesDatabase[ruleId]||rulesDatabase["no-hallucinated-package-manifest"];currentDrawerRule=data.id;document.getElementById("drawerRuleId").textContent=data.id;const sevEl=document.getElementById("drawerSeverity");sevEl.className=`severity-pill ${data.sevClass}`;sevEl.textContent=data.severity;document.getElementById("drawerCategory").textContent=data.category;const iconEl=document.getElementById("drawerIcon");iconEl.setAttribute("stroke",data.iconStroke);iconEl.innerHTML=data.icon;document.getElementById("drawerSummary").textContent=data.summary;const threatsList=document.getElementById("drawerThreats");threatsList.innerHTML=data.threats.map(t=>`<li class="drawer-threat-item"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ff3366" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg><span>${t}</span></li>`).join("");document.getElementById("drawerExclusions").textContent=data.exclusions;switchDrawerLang(currentDrawerLang||"js");backdrop.classList.add("open");drawer.classList.add("open");drawer.setAttribute("aria-hidden","false");}
function closeRuleDrawer(){const drawer=document.getElementById("ruleDrawer");const backdrop=document.getElementById("ruleDrawerBackdrop");if(!drawer||!backdrop)return;drawer.classList.remove("open");backdrop.classList.remove("open");drawer.setAttribute("aria-hidden","true");}
function switchDrawerLang(lang){currentDrawerLang=lang;document.querySelectorAll(".drawer-lang-btn").forEach(btn=>btn.classList.remove("active"));const btn=document.getElementById(`tab${lang.charAt(0).toUpperCase()+lang.slice(1)}`);if(btn)btn.classList.add("active");const data=rulesDatabase[currentDrawerRule]||rulesDatabase["no-hallucinated-package-manifest"];const codeEl=document.getElementById("drawerCode");if(codeEl&&data.snippets&&data.snippets[lang]){codeEl.textContent=data.snippets[lang];}}
function copyDrawerCode(btn){const codeEl=document.getElementById("drawerCode");if(!codeEl)return;navigator.clipboard.writeText(codeEl.textContent).then(()=>{const orig=btn.innerHTML;btn.innerHTML=`<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2"><path d="M20 6L9 17l-5-5"></path></svg>`;setTimeout(()=>{btn.innerHTML=orig;},1600);});}
document.addEventListener("DOMContentLoaded",()=>{initWaveform();renderFirewallGrid();const editor=document.getElementById("liveCodeEditor");if(editor){editor.addEventListener("input",(e)=>auditCode(e.target.value));auditCode(editor.value);}document.addEventListener("keydown",(e)=>{if(e.key==="Escape")closeRuleDrawer();});});
